use hs_loop::dshskill::*;use serde_json::{json,Value};use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Provider{name:String,rank:f64,content:std::sync::Mutex<String>,gets:AtomicUsize,fail:bool,policy:Invocation,loaded_name:Option<String>}
impl SkillProvider for Provider{fn name(&self)->&str{&self.name}fn list(&self)->Result<ProviderObservation,String>{if self.fail{return Err("discovery unavailable".into())}Ok(ProviderObservation{complete:true,candidates:vec![Candidate{name:"alpha".into(),description:"Remote summary".into(),provider:self.name.clone(),source:"remote-source".into(),rank:self.rank,invocation:self.policy.clone(),locator:json!({"remote-id":7})}]})}fn get(&self,c:&Candidate)->Result<Option<RuntimeSkill>,String>{assert_eq!(c.locator,json!({"remote-id":7}));self.gets.fetch_add(1,Ordering::SeqCst);Ok(Some(RuntimeSkill{name:self.loaded_name.clone().unwrap_or(c.name.clone()),description:c.description.clone(),source:c.source.clone(),provider:self.name.clone(),content:self.content.lock().unwrap().clone(),invocation:self.policy.clone(),resource_base:Some(json!({"kind":"opaque","description":"remote id 7"}))}))}}
fn provider(name:&str,rank:f64)->Arc<Provider>{Arc::new(Provider{name:name.into(),rank,content:std::sync::Mutex::new(name.into()),gets:AtomicUsize::new(0),fail:false,policy:Invocation::default(),loaded_name:None})}
#[test]fn provider_summary_does_not_load_body_and_get_uses_locator_fresh(){let p=provider("remote",50.0);let mut r=Registry::default();r.register_provider(None,p.clone()).unwrap();assert_eq!(r.catalog(&[]).unwrap(),json!([{"name":"alpha","description":"Remote summary"}]));assert_eq!(p.gets.load(Ordering::SeqCst),0);assert_eq!(r.call(&[],&json!({"name":"alpha"})).unwrap()["content"],"remote");*p.content.lock().unwrap()="new body".into();assert_eq!(r.call(&[],&json!({"name":"alpha"})).unwrap()["content"],"new body");assert_eq!(p.gets.load(Ordering::SeqCst),2);}
#[test]fn provider_rank_registration_order_scope_and_teardown_define_winner(){let mut r=Registry::default();r.register_provider(None,provider("first",300.0)).unwrap();r.register_provider(None,provider("second",300.0)).unwrap();assert_eq!(r.call(&[],&json!({"name":"alpha"})).unwrap()["provider"],"first");assert!(r.register_provider(None,provider("first",1.0)).is_err());assert!(r.register_provider(None,provider("runtime",1.0)).is_err());r.register_provider(Some("child"),provider("near",999.0)).unwrap();assert_eq!(r.call_scoped(&[],&["child".into()],&json!({"name":"alpha"})).unwrap()["provider"],"near");assert!(r.remove_provider(Some("child"),"near"));assert_eq!(r.call_scoped(&[],&["child".into()],&json!({"name":"alpha"})).unwrap()["provider"],"first");assert!(r.remove_provider(None,"first"));assert_eq!(r.call(&[],&json!({"name":"alpha"})).unwrap()["provider"],"second");assert!(!r.remove_provider(None,"first"));}
#[test]fn failed_provider_does_not_poison_other_provider_and_stale_loaded_name_is_unknown(){let mut r=Registry::default();let mut p=provider("broken",1.0);Arc::get_mut(&mut p).unwrap().fail=true;r.register_provider(None,p).unwrap();r.register_provider(None,provider("good",300.0)).unwrap();assert_eq!(r.call(&[],&json!({"name":"alpha"})).unwrap()["provider"],"good");let mut p=provider("stale",1.0);Arc::get_mut(&mut p).unwrap().loaded_name=Some("beta".into());r.register_provider(None,p).unwrap();assert!(r.call(&[],&json!({"name":"alpha"})).unwrap_err().contains("unknown or no longer available"));}
#[test]fn disabled_provider_winner_does_not_load_or_fallback(){let mut r=Registry::default();let mut p=provider("hidden",1.0);Arc::get_mut(&mut p).unwrap().policy.model_invocable=false;r.register_provider(None,p.clone()).unwrap();r.register_provider(None,provider("fallback",999.0)).unwrap();assert!(r.catalog(&[]).unwrap().as_array().unwrap().is_empty());assert!(r.call(&[],&json!({"name":"alpha"})).unwrap_err().contains("not available for model invocation"));assert_eq!(p.gets.load(Ordering::SeqCst),0);assert_eq!(r.direct(&[],"Use /alpha").unwrap()[0]["provider"],"hidden");}
struct FlipsUserPolicy;impl SkillProvider for FlipsUserPolicy{fn name(&self)->&str{"flip"}fn list(&self)->Result<ProviderObservation,String>{Ok(ProviderObservation{complete:true,candidates:vec![Candidate{name:"alpha".into(),description:"A".into(),provider:"flip".into(),source:"remote".into(),rank:1.0,invocation:Invocation::default(),locator:Value::Null}]})}fn get(&self,_:&Candidate)->Result<Option<RuntimeSkill>,String>{Ok(Some(RuntimeSkill{name:"alpha".into(),description:"A".into(),source:"remote".into(),provider:"flip".into(),content:"Forbidden direct body".into(),invocation:Invocation{model_invocable:false,user_invocable:false},resource_base:None}))}}
#[test]fn changed_definition_policy_is_rechecked_for_direct_user_not_only_summary(){let mut r=Registry::default();r.register_provider(None,Arc::new(FlipsUserPolicy)).unwrap();assert!(r.direct(&[],"/alpha").unwrap().is_empty());assert!(r.call(&[],&json!({"name":"alpha"})).unwrap_err().contains("not available for model invocation"));}
#[test]fn provider_is_available_to_actual_loop_catalog_and_direct_user_injection(){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,1).unwrap();lp.set_answer_root(Some(d.path().to_owned()));lp.register_skill_provider(Some("child"),provider("actual",50.0)).unwrap();lp.set_skill_scope_chain(vec!["child".into()]);assert_eq!(lp.user_skill_names().unwrap(),vec!["alpha"]);lp.run_root_human_mission("remote","Use /alpha").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().any(|v|v["record_type"]=="skill/catalog"&&v["entries"][0]["description"]=="Remote summary"));assert!(vals.iter().any(|v|v["record_type"]=="skill/invocation"&&v["value"]["provider"]=="actual"));assert!(vals.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|v|v["content"].as_str().is_some_and(|s|s.contains("Resources for this skill: remote id 7")))));}
struct Incomplete;impl SkillProvider for Incomplete{fn name(&self)->&str{"incomplete"}fn list(&self)->Result<ProviderObservation,String>{Ok(ProviderObservation{candidates:vec![],complete:false})}fn get(&self,_:&Candidate)->Result<Option<RuntimeSkill>,String>{Ok(None)}}
#[test]fn failed_or_incomplete_discovery_never_claims_complete_snapshot(){for failed in [false,true]{let mut r=Registry::default();if failed{let mut p=provider("broken",1.0);Arc::get_mut(&mut p).unwrap().fail=true;r.register_provider(None,p).unwrap();}else{r.register_provider(Some("near"),Arc::new(Incomplete)).unwrap();}r.register_provider(None,provider("good",50.0)).unwrap();let(entries,complete)=r.snapshot_scoped(&[],&["near".into()]).unwrap();assert_eq!(entries[0]["name"],"alpha");assert!(!complete);}}
struct BecomesIncomplete{calls:AtomicUsize}impl SkillProvider for BecomesIncomplete{fn name(&self)->&str{"changing"}fn list(&self)->Result<ProviderObservation,String>{let first=self.calls.fetch_add(1,Ordering::SeqCst)==0;Ok(ProviderObservation{complete:first,candidates:if first{vec![Candidate{name:"alpha".into(),description:"Last good catalog".into(),provider:"changing".into(),source:"remote".into(),rank:1.0,invocation:Invocation::default(),locator:Value::Null}]}else{vec![]}})}fn get(&self,_:&Candidate)->Result<Option<RuntimeSkill>,String>{Ok(None)}}
#[test]fn incomplete_next_step_retains_last_good_catalog_in_actual_request(){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,2).unwrap();lp.set_answer_root(Some(d.path().to_owned()));lp.register_skill_provider(None,Arc::new(BecomesIncomplete{calls:AtomicUsize::new(0)})).unwrap();lp.run_mission("incomplete").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let calls:Vec<_>=vals.iter().filter(|v|v["messages"].is_array()).collect();assert!(calls.len()>1);for call in calls{assert!(call["messages"].as_array().unwrap().iter().any(|m|m["content"].as_str().is_some_and(|s|s.contains("- `alpha`: Last good catalog"))));}assert_eq!(vals.iter().filter(|v|v["record_type"]=="skill/catalog").count(),1);}
